    @Override public int applyMending(int amount) {
        requireWritable();
        var handle = getHandle();
        var entry = net.minecraft.enchantment.EnchantmentHelper.chooseEquipmentWith(
                net.minecraft.enchantment.Enchantments.MENDING, handle, net.minecraft.item.ItemStack::isDamaged);
        if (entry == null) return amount;
        var item = entry.getValue();
        var orb = new net.minecraft.entity.ExperienceOrbEntity(handle.getWorld(), handle.getX(), handle.getY(), handle.getZ(), amount);
        ((dev.meldrite.v1201.compat.ExperienceOrbNativeAccess) (Object) orb).meldrite$setSpawnReason(org.bukkit.entity.ExperienceOrb.SpawnReason.CUSTOM);
        var event = new org.bukkit.event.player.PlayerItemMendEvent(this,
                org.bukkit.craftbukkit.v1_20_R1.inventory.CraftItemStack.asCraftMirror(item),
                org.bukkit.craftbukkit.v1_20_R1.CraftEquipmentSlot.getSlot(entry.getKey()),
                (org.bukkit.entity.ExperienceOrb) dev.meldrite.v1201.compat.NativeEntityExtensions.bukkit(orb),
                Math.min(amount * 2, item.getDamage()), durability -> durability / 2);
        try {
            getServer().getPluginManager().callEvent(event);
            if (!event.isCancelled()) {
                int repair = event.getRepairAmount();
                amount -= event.getDurabilityToXpOperation().applyAsInt(repair);
                item.setDamage(item.getDamage() - repair);
            }
            return amount;
        } finally { orb.discard(); }
    }
