        if (playerWorldBorder != null && playerWorldBorderListener != null) playerWorldBorder.getHandle().removeListener(playerWorldBorderListener);
        playerWorldBorder = (org.bukkit.craftbukkit.v1_20_R1.CraftWorldBorder) border;
        playerWorldBorderListener = null;
