    private static net.minecraft.world.border.WorldBorderListener borderListener(CraftPlayer owner) {
            var reference = new java.lang.ref.WeakReference<>(owner);
            return new net.minecraft.world.border.WorldBorderListener() {
                private void changed(net.minecraft.world.border.WorldBorder value) {
                    var player = reference.get();
                    if (player == null) { value.removeListener(this); return; }
                    if (player != null && player.playerWorldBorder != null && player.playerWorldBorder.getHandle() == value)
                        player.sendPlayerPacket(new net.minecraft.network.packet.s2c.play.WorldBorderInitializeS2CPacket(value));
                }
                public void onSizeChange(net.minecraft.world.border.WorldBorder value, double size) { changed(value); }
                public void onInterpolateSize(net.minecraft.world.border.WorldBorder value, double from, double to, long millis) { changed(value); }
                public void onCenterChanged(net.minecraft.world.border.WorldBorder value, double x, double z) { changed(value); }
                public void onWarningTimeChanged(net.minecraft.world.border.WorldBorder value, int time) { changed(value); }
                public void onWarningBlocksChanged(net.minecraft.world.border.WorldBorder value, int distance) { changed(value); }
                public void onDamagePerBlockChanged(net.minecraft.world.border.WorldBorder value, double damage) { }
                public void onSafeZoneChanged(net.minecraft.world.border.WorldBorder value, double distance) { }
            };
    }
