    @Override public void chat(java.lang.String message) {
        if (message == null) throw new IllegalArgumentException("message cannot be null");
        if (!getServer().isPrimaryThread()) throw new IllegalStateException("ASYNC_PLAYER_CHAT");
        if (getHandle().networkHandler == null) return;
        for (int index = 0; index < message.length(); index++) {
            if (!net.minecraft.SharedConstants.isValidChar(message.charAt(index))) {
                kick(net.kyori.adventure.text.Component.translatable("multiplayer.disconnect.illegal_characters"), org.bukkit.event.player.PlayerKickEvent.Cause.ILLEGAL_CHARACTERS);
                return;
            }
        }
        if (message.startsWith("/")) dev.meldrite.v1201.compat.NativePlayerChat.command(this, message);
        else if (!message.isEmpty() && getHandle().getClientChatVisibility() == net.minecraft.client.option.ChatVisibility.FULL) dev.meldrite.v1201.compat.NativePlayerChat.message(this, message);
    }
