    @Override public <T extends java.lang.Object> T getClientOption(com.destroystokyo.paper.ClientOption<T> option) {
        java.util.Objects.requireNonNull(option, "option"); Object value;
        if (option == com.destroystokyo.paper.ClientOption.LOCALE) value = getLocale();
        else if (option == com.destroystokyo.paper.ClientOption.VIEW_DISTANCE) value = getClientViewDistance();
        else if (option == com.destroystokyo.paper.ClientOption.CHAT_COLORS_ENABLED) value = getHandle().areClientChatColorsEnabled();
        else if (option == com.destroystokyo.paper.ClientOption.CHAT_VISIBILITY) value = com.destroystokyo.paper.ClientOption.ChatVisibility.valueOf(getHandle().getClientChatVisibility().name());
        else if (option == com.destroystokyo.paper.ClientOption.MAIN_HAND) value = getHandle().getMainArm() == net.minecraft.util.Arm.LEFT ? org.bukkit.inventory.MainHand.LEFT : org.bukkit.inventory.MainHand.RIGHT;
        else if (option == com.destroystokyo.paper.ClientOption.ALLOW_SERVER_LISTINGS) value = getHandle().allowsServerListing();
        else if (option == com.destroystokyo.paper.ClientOption.TEXT_FILTERING_ENABLED) value = getHandle().shouldFilterText();
        else if (option == com.destroystokyo.paper.ClientOption.SKIN_PARTS) value = new dev.meldrite.v1201.compat.NativeSkinParts(playerState().skinParts);
        else throw new IllegalArgumentException("Unknown client option: " + option);
        return option.getType().cast(value);
    }
