    private void changeEntityVisibility(org.bukkit.plugin.Plugin plugin, org.bukkit.entity.Entity entity, boolean visible) {
        java.util.Objects.requireNonNull(entity, "entity"); requireWritable();
        if (getHandle().networkHandler == null || getUniqueId().equals(entity.getUniqueId())) return;
        if (!(entity instanceof CraftEntity nativeEntity)) throw new IllegalArgumentException("Entity is not native");
        if (playerState().visibility(entity.getUniqueId(), entity.isVisibleByDefault(), plugin, visible)) {
            dev.meldrite.v1201.compat.NativePlayerVisibility.update(getHandle(), nativeEntity.getHandle(), canSee(entity));
            getServer().getPluginManager().callEvent(visible ? new org.bukkit.event.player.PlayerShowEntityEvent(this, entity) : new org.bukkit.event.player.PlayerHideEntityEvent(this, entity));
        }
    }
