    @Override public void kick(net.kyori.adventure.text.Component reason, org.bukkit.event.player.PlayerKickEvent.Cause cause) {
        if (!getServer().isPrimaryThread()) throw new IllegalStateException("ASYNC_PLAYER_KICK");
        var connection = getHandle().networkHandler; if (connection == null) return;
        var event = new org.bukkit.event.player.PlayerKickEvent(this, reason == null ? net.kyori.adventure.text.Component.empty() : reason,
                net.kyori.adventure.text.Component.translatable("multiplayer.player.left", name()), java.util.Objects.requireNonNull(cause, "cause"));
        getServer().getPluginManager().callEvent(event);
        if (!event.isCancelled()) {
            playerState().kickLeaveMessage = event.leaveMessage(); playerState().kickLeaveMessageSet = true;
            connection.disconnect(componentText(event.reason()));
        }
    }
