    @Override public void openBook(org.bukkit.inventory.ItemStack book) {
        if (book == null || book.getType() != org.bukkit.Material.WRITTEN_BOOK) throw new IllegalArgumentException("A written book is required");
        if (getHandle().networkHandler == null) return;
        requireWritable();
        var inventory = getHandle().getInventory();
        var hand = inventory.getMainHandStack();
        try {
            var nativeBook = org.bukkit.craftbukkit.v1_20_R1.inventory.CraftItemStack.asNMSCopy(book);
            inventory.setStack(inventory.selectedSlot, nativeBook);
            getHandle().currentScreenHandler.syncState();
            getHandle().useBook(nativeBook, net.minecraft.util.Hand.MAIN_HAND);
        } finally {
            inventory.setStack(inventory.selectedSlot, hand);
            getHandle().currentScreenHandler.syncState();
        }
    }
