    @Override public void sendPluginMessage(org.bukkit.plugin.Plugin source, java.lang.String channel, byte[] message) {
        org.bukkit.plugin.messaging.StandardMessenger.validatePluginMessage(getServer().getMessenger(), source, channel, message);
        String wireChannel = channel.equals("BungeeCord") ? "bungeecord:main" : channel;
        if (getHandle().networkHandler == null || !playerState().channels.contains(wireChannel)) return;
        var id = new net.minecraft.util.Identifier(wireChannel);
        sendPlayerPacket(new net.minecraft.network.packet.s2c.play.CustomPayloadS2CPacket(id,
                new net.minecraft.network.PacketByteBuf(io.netty.buffer.Unpooled.wrappedBuffer(message))));
    }
    @Override public void sendSignChange(org.bukkit.Location location, java.util.List<? extends net.kyori.adventure.text.Component> lines, org.bukkit.DyeColor color, boolean glow) {
        if (lines != null && lines.size() < 4) throw new IllegalArgumentException("At least four lines are required");
        var text = new net.minecraft.text.Text[4];
        for (int line = 0; line < 4; line++) text[line] = lines == null ? net.minecraft.text.Text.empty() : componentText(lines.get(line));
        sendSignText(location, text, color, glow);
    }
    @Override public void sendSignChange(org.bukkit.Location location, java.lang.String[] lines) { sendSignChange(location, lines, org.bukkit.DyeColor.BLACK, false); }
    @Override public void sendSignChange(org.bukkit.Location location, java.lang.String[] lines, org.bukkit.DyeColor color) { sendSignChange(location, lines, color, false); }
    @Override public void sendSignChange(org.bukkit.Location location, java.lang.String[] lines, org.bukkit.DyeColor color, boolean glow) {
        if (lines != null && lines.length < 4) throw new IllegalArgumentException("At least four lines are required");
        var text = new net.minecraft.text.Text[4];
        for (int line = 0; line < 4; line++) text[line] = legacyText(lines == null ? null : lines[line]);
        sendSignText(location, text, color, glow);
    }
    private void sendSignText(org.bukkit.Location location, net.minecraft.text.Text[] lines, org.bukkit.DyeColor color, boolean glow) {
        if (location == null || color == null) throw new IllegalArgumentException("Location and color are required");
        if (getHandle().networkHandler == null) return;
        var position = new net.minecraft.util.math.BlockPos(location.getBlockX(), location.getBlockY(), location.getBlockZ());
        var sign = new net.minecraft.block.entity.SignBlockEntity(position, net.minecraft.block.Blocks.OAK_SIGN.getDefaultState());
        var text = sign.getFrontText().withColor(net.minecraft.util.DyeColor.byId(color.getWoolData())).withGlowing(glow);
        for (int line = 0; line < 4; line++) text = text.withMessage(line, lines[line]);
        var tag = sign.createNbt();
        tag.put("front_text", net.minecraft.block.entity.SignText.CODEC.encodeStart(net.minecraft.nbt.NbtOps.INSTANCE, text)
                .result().orElseThrow(() -> new IllegalArgumentException("Invalid sign text")));
        sendPlayerPacket(net.minecraft.network.packet.s2c.play.BlockEntityUpdateS2CPacket.create(sign, ignored -> tag));
    }
