        sendPlayerPacket(new net.minecraft.network.packet.s2c.play.WorldTimeUpdateS2CPacket(world.getTime(), getPlayerTime(), isPlayerTimeRelative() && world.getGameRules().getBoolean(net.minecraft.world.GameRules.DO_DAYLIGHT_CYCLE)));
