    @Override public void setPlayerWeather(org.bukkit.WeatherType weather) { java.util.Objects.requireNonNull(weather, "weather"); requireWritable(); playerState().weather = weather; sendPlayerWeather(); }
    private void sendPlayerWeather() {
        var world = getHandle().getServerWorld(); var override = getPlayerWeather();
        boolean raining = override == null ? world.isRaining() : override == org.bukkit.WeatherType.DOWNFALL;
        sendPlayerPacket(new net.minecraft.network.packet.s2c.play.GameStateChangeS2CPacket(raining ? net.minecraft.network.packet.s2c.play.GameStateChangeS2CPacket.RAIN_STARTED : net.minecraft.network.packet.s2c.play.GameStateChangeS2CPacket.RAIN_STOPPED, 0));
        sendPlayerPacket(new net.minecraft.network.packet.s2c.play.GameStateChangeS2CPacket(net.minecraft.network.packet.s2c.play.GameStateChangeS2CPacket.RAIN_GRADIENT_CHANGED, override == null ? world.getRainGradient(1) : raining ? 1 : 0));
        sendPlayerPacket(new net.minecraft.network.packet.s2c.play.GameStateChangeS2CPacket(net.minecraft.network.packet.s2c.play.GameStateChangeS2CPacket.THUNDER_GRADIENT_CHANGED, override == null ? world.getThunderGradient(1) : 0));
    }
